import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DncwoWA8.js";const u=JSON.parse('{"title":"Regenerate and review diagrams","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/diagrams.md","filePath":"maintenance/diagrams.md"}'),r={name:"maintenance/diagrams.md"};function n(o,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="regenerate-and-review-diagrams" tabindex="-1">Regenerate and review diagrams <a class="header-anchor" href="#regenerate-and-review-diagrams" aria-label="Permalink to &quot;Regenerate and review diagrams&quot;">​</a></h1><p>Normal site builds use the checked-in diagram outputs. Regeneration is an explicit authoring operation with network, executable-code, browser, and filesystem effects. Follow the project&#39;s approval and isolated-workspace rules first.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Complete the <a href="/projects/ai-skills/maintenance/">mise setup</a> and approve any missing tools. Archify is an upstream-only catalog entry, not a vendored skill or registered live-agent installation. The setup task acquires the catalog-pinned package into an external <code>ai-skills-docs</code> tool cache under <code>XDG_CACHE_HOME</code> or the standard user cache. It does not change personal agent discovery paths or install a browser.</p><p>You need Node.js and an existing Chrome, Chromium, or Edge compatible with Archify. This project&#39;s browser helper defaults to <code>chromium</code>; set <code>ARCHIFY_CHROME</code> to a reviewed executable path when needed. An invalid explicit path fails rather than silently choosing another browser. The helper uses an isolated disposable profile and a private DevTools pipe, not a personal browser profile.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> run</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> docs:diagrams:setup</span></span></code></pre></div><p>Read the installed <code>SKILL.md</code> and the references required by the selected diagram type before authoring. The immutable package revision is recorded in the catalog. Setup preserves the complete package and legal files; it does not run downloaded code merely to inspect it. A changed cache or provenance mismatch stops reuse instead of silently replacing it.</p><h2 id="author-and-regenerate" tabindex="-1">Author and regenerate <a class="header-anchor" href="#author-and-regenerate" aria-label="Permalink to &quot;Author and regenerate&quot;">​</a></h2><p>The five primary workflow diagrams live in <code>scripts/docs/workflow-guide-diagrams.mjs</code>. Their titles and the focused recipe definitions live in <code>scripts/docs/workflows.mjs</code>. The shared <code>scripts/docs/diagram-specs.mjs</code> builds native candidates with source references from the actual catalog. Required instruction edges come from catalog prerequisites and are checked against local frontmatter. Never infer an extra dependency from a useful companion or later phase.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> run</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> docs:diagrams</span></span></code></pre></div><p>For a focused repair, pass only known diagram IDs:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> exec</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> node</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> scripts/docs/archify.mjs</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> render</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> plan-a-project</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> implement-a-task</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> debug-a-problem</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> document-a-project</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> debloat-a-project</span></span></code></pre></div><p>The renderer runs the full native <code>finalize</code> contract at showcase quality: validation, delivery, strict artifact checks, and real-browser checks. It then uses the actual Viewer export controls to obtain canonical dual-theme SVGs. A failed gate exits nonzero; it is not normalized to success or a skipped check.</p><table tabindex="0"><thead><tr><th>Artifact</th><th>Location</th></tr></thead><tbody><tr><td>Editable native JSON</td><td><code>docs/diagrams/&lt;id&gt;.json</code></td></tr><tr><td>Published standalone HTML and SVG</td><td><code>docs/public/diagrams/&lt;id&gt;.html</code> and <code>&lt;id&gt;.svg</code></td></tr><tr><td>Source/output hashes and compact gate results</td><td><code>docs/diagrams/manifest.json</code></td></tr><tr><td>Original native HTML, delivery receipts, and per-run evidence</td><td><code>.docs-artifacts/archify/</code> (ignored, not published)</td></tr><tr><td>Downloadable source copies</td><td><code>docs/public/diagram-sources/</code> (generated for serving)</td></tr><tr><td>Preserved Archify software and font notices</td><td><code>docs/public/notices/archify/</code></td></tr></tbody></table><p>The published HTML is a byte-identical copy of the finalized native artifact, checked against its receipt. SVG exports are communication assets; they do not replace native artifact provenance or perceptual review. Do not minify or hand-edit a verified HTML/SVG without a new regeneration and review.</p><p>Native receipts may contain local evidence paths, so they stay in the ignored developer-artifact directory. The checked-in manifest contains portable hashes and source identities, not private machine paths. Build-time public source/manifest copies are derived, not competing editable sources.</p><h2 id="review-what-the-reader-will-see" tabindex="-1">Review what the reader will see <a class="header-anchor" href="#review-what-the-reader-will-see" aria-label="Permalink to &quot;Review what the reader will see&quot;">​</a></h2><p>Automated browser checks prove measured containment and runtime checks at the tool&#39;s required desktop viewports. They do not prove that a diagram teaches the right thing or that a human can use the site.</p><p>Inspect the actual outputs for readable labels, arrow direction, conditional approval edges, no misleading service or dependency claims, and correct stopping points. Compare the diagram with its text steps and the authoritative source. Verify light/dark presentation, static SVG, and the standalone Viewer separately.</p><p>For native perceptual captures, follow the installed delivery contract&#39;s <code>visual-check</code> procedure, preserve its evidence set, and inspect the captures before claiming visual review. Use a fresh evidence directory after any candidate change; old screenshots remain bound to the old artifact bytes.</p><p>Interactive HTML links use the Markdown attribute <code>{class=&quot;vp-raw&quot;}</code>. VitePress leaves these links to normal browser navigation while still adding the configured base path. Keep this class on standalone diagram links; an ordinary internal link can open the missing-page route instead of the Viewer. Do not substitute a <code>target</code> attribute on a root-absolute link, because VitePress 1.6.4 then skips base-path rewriting.</p><p>The native Viewer is desktop-oriented. On a phone, the site provides a static preview and the full text steps; containment does not promise desktop feature parity in the standalone Viewer.</p><p>Finish with <code>mise run docs:check</code>, both base-path builds, and browser review of the actual site. Report artifact gates, automated browser evidence, agent visual inspection, and actual human testing as separate claims.</p>',23)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
